<template><Teleport to="body"><div class="outcome-backdrop" @click.self="$emit('close')" @keydown.esc.prevent="$emit('close')" @keydown.tab="trapFocus"><section role="dialog" aria-modal="true" aria-labelledby="outcome-title" ref="dialog" tabindex="-1" class="outcome-dialog"><button @click="$emit('close')">Close</button><h2 id="outcome-title">Appointment #{{appointmentId}}</h2><p v-if="loading" role="status">Loading appointment history…</p><p v-if="error" role="alert">{{error}}</p><template v-if="record"><p>{{label}}</p><p>{{when(record.startAt)}} – {{when(record.endAt)}}</p><p>This appointment has an attendance outcome. Its saved time and location are read-only.</p><router-link v-if="learning" :to="hub" @click="$emit('close')">Open Session Hub</router-link><AppointmentNoShowStatus :appointment-id="appointmentId" @undone="$emit('changed');load()" /><button v-if="missed && learning && canBook" class="makeup" @click="$emit('makeup',record)">Reschedule · book a makeup</button><p v-if="missed && learning && canBook">Choose a new date and review the booking. The missed appointment stays in history.</p><p v-else-if="missed">Contact Support to arrange a makeup. Keep this missed appointment in history when booking a new session.</p></template></section></div></Teleport></template>
<script setup>
import {ref,computed,watch,onBeforeUnmount,onMounted} from 'vue';import {useRoute} from 'vue-router';import api from '../../services/api';import AppointmentNoShowStatus from './AppointmentNoShowStatus.vue';
const props=defineProps({appointmentId:{type:Number,required:true},canBook:Boolean});defineEmits(['close','changed','makeup']);const dialog=ref(null);const previousFocus=document.activeElement;const route=useRoute();const record=ref(null),loading=ref(true),error=ref('');let generation=0;
const learning=computed(()=>['tutoring','learning'].includes(record.value?.businessType));const missed=computed(()=>['no_show','late_canceled','no_show_pending'].includes(record.value?.status));const label=computed(()=>record.value?.displayStatus||String(record.value?.attendanceStatus||record.value?.status||'').replaceAll('_',' '));const hub=computed(()=>`${route.params.organizationSlug?'/'+route.params.organizationSlug:''}/tutoring-session/appointment/${props.appointmentId}`);const when=v=>v?new Date(String(v).includes('T')?v:String(v).replace(' ','T')+'Z').toLocaleString('en-US',{timeZone:record.value?.sourceTimezone||'America/Denver',dateStyle:'medium',timeStyle:'short'}):'—';
async function load(){const own=++generation;record.value=null;error.value='';loading.value=true;try{const{data}=await api.get(`/appointments/${props.appointmentId}`,{skipGlobalLoading:true});if(own===generation)record.value=data.appointment||data;}catch(e){if(own===generation)error.value=e.response?.data?.error?.message||'This attendance record could not be opened. Contact Support.';}finally{if(own===generation)loading.value=false;}}
function trapFocus(e){const nodes=[...(dialog.value?.querySelectorAll('button:not(:disabled),a[href],textarea,input,[tabindex="0"]')||[])];if(!nodes.length)return;const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
watch(()=>props.appointmentId,load,{immediate:true});onMounted(()=>dialog.value?.focus());onBeforeUnmount(()=>{generation++;previousFocus?.focus?.();});
</script>
<style scoped>.outcome-backdrop{position:fixed;inset:0;background:#102f3280;z-index:11000;display:grid;place-items:center;padding:20px}.outcome-dialog{background:white;color:#173451;padding:24px;border-radius:14px;width:min(600px,100%);max-height:85vh;overflow:auto}.outcome-dialog button{float:right;padding:10px}.outcome-dialog .makeup{float:none;display:block;margin:12px 0}.outcome-dialog a{display:inline-block;padding:12px}</style>
